// --- Input format: OpenAI Chat response (like the one you pasted) ---
// Expected fields: $json.message.content

let raw = $json.message?.content || $json.content;
if (!raw) throw new Error("No GPT output found.");

// --- Clean & Parse JSON safely ---
let parsed;
try {
  raw = raw.replace(/```json|```/g, "").trim();
  parsed = JSON.parse(raw);
} catch (err) {
  throw new Error("Invalid JSON in GPT output: " + err.message);
}

// --- Extract scenes & music mood ---
const scenes = parsed.scenes || [];
const musicMood = parsed.music_mood || "cinematic";

// --- Collect keywords & SRT captions ---
let srt = "";
let counter = 1;
const bestKeywords = [];

function toTimestamp(seconds) {
  const s = Math.floor(Number(seconds));
  const h = String(Math.floor(s / 3600)).padStart(2, "0");
  const m = String(Math.floor((s % 3600) / 60)).padStart(2, "0");
  const sec = String(s % 60).padStart(2, "0");
  return `${h}:${m}:${sec},000`;
}

scenes.forEach(scene => {
  if (scene.keyword) bestKeywords.push(scene.keyword);

  if (scene.text && scene.timing) {
    const [start, end] = scene.timing.replace(/s/g, "").split("-");
    srt += `${counter}\n${toTimestamp(start)} --> ${toTimestamp(end)}\n${scene.text}\n\n`;
    counter++;
  }
});

// --- Return structured data for downstream nodes ---
return [
  {
    json: {
      scenes,
      bestKeywords,
      srt,
      musicMood
    }
  }
];

