let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  throw new Error("Could not parse AI JSON: " + e.message + " | Raw: " + raw);
}

const scenes = [];
const bestKeywords = [];
let srt = "";
let counter = 1;

function toTimestamp(seconds) {
  const sec = parseInt(seconds, 10);
  const h = String(Math.floor(sec / 3600)).padStart(2, "0");
  const m = String(Math.floor((sec % 3600) / 60)).padStart(2, "0");
  const s = String(sec % 60).padStart(2, "0");
  return `${h}:${m}:${s},000`;
}

(parsed.scenes || []).forEach(scene => {
  const keywords = scene.keywords || [];
  const filtered = keywords.filter(k =>
    !["promotion", "discount", "cta", "offer"].some(weak =>
      k.toLowerCase().includes(weak)
    )
  );
  const list = filtered.length > 0 ? filtered : keywords;
  const best = list.length > 0 ? list.reduce((a, b) => (a.length >= b.length ? a : b)) : null;
  if (best) bestKeywords.push(best);

  scenes.push({
    ...scene,
    keyword: best
  });

  // Use ChatGPT's provided timing directly
  if (scene.caption && scene.timing) {
    const [start, end] = scene.timing.replace(/s/g, "").split("-");
    srt += `${counter}\n${toTimestamp(start)} --> ${toTimestamp(end)}\n${scene.caption}\n\n`;
    counter++;
  }
});

return [{
  json: {
    scenes,
    bestKeywords,
    srt
  }
}];

