// === Pexels + Voiceover + Background Music → Shotstack JSON ===

// ---------- 1. Gather Inputs ----------
const videos = $json.videos || [];
const music = $json.selectedMusic?.direct || null;
const voiceover = $json.directUrl || null;
const srtText = $json.data || $json.srt || null;

// ---------- 2. Parse SRT for exact voiceover duration ----------
function toSeconds(ts) {
  const [h, m, s] = ts.split(":");
  const [sec, ms] = s.split(",");
  return (+h) * 3600 + (+m) * 60 + (+sec) + (+ms || 0) / 1000;
}

function parseSRT(srt) {
  if (!srt) return [];
  const blocks = srt.trim().split(/\n\n+/);
  return blocks
    .map((block) => {
      const lines = block.split("\n");
      if (lines.length < 2) return null;
      const [start, end] = lines[1].split(" --> ");
      return { start: toSeconds(start), end: toSeconds(end) };
    })
    .filter(Boolean);
}

// Parse and get duration
const captions = parseSRT(srtText);
const voiceDuration = captions.length > 0 ? captions[captions.length - 1].end : null;

// ---------- 3. Determine target duration ----------
let targetDuration;
if (voiceDuration && voiceDuration > 0) {
  targetDuration = voiceDuration;  // ✅ use exact detected duration
} else {
  targetDuration = 30;             // ⚙️ fallback only when missing
}

// ---------- 4. Build video clips ----------
const numClips = Math.min(6, videos.length);
const clipLength = targetDuration / numClips;

let currentStart = 0;
const videoClips = videos.slice(0, numClips).map((v, i) => {
  const hdFile =
    v.video_files.find((f) => f.width >= 1080) ||
    v.video_files.find((f) => f.width >= 720) ||
    v.video_files[0];

  const isLast = i === numClips - 1;
  const length = isLast ? targetDuration - currentStart : clipLength;

  const clip = {
    asset: { type: "video", src: hdFile.link },
    fit: "contain",
    start: currentStart,
    length,
  };
  currentStart += length;
  return clip;
});

// ---------- 5. Audio Layers ----------
const audioTracks = [];

// 🎙 Voiceover
if (voiceover) {
  audioTracks.push({
    clips: [
      {
        asset: {
          type: "audio",
          src: voiceover,
          volume: 1.0,
        },
        start: 0,
        length: targetDuration,
      },
    ],
  });
}

// 🎵 Background Music (fade-out at end)
if (music) {
  const fadeStart = Math.max(targetDuration - 3, 0);
  audioTracks.push({
    clips: [
      {
        asset: { type: "audio", src: music, volume: 0.3 },
        start: 0,
        length: fadeStart,
      },
      {
        asset: { type: "audio", src: music, volume: 0.1 },
        start: fadeStart,
        length: targetDuration - fadeStart,
      },
    ],
  });
}

// ---------- 6. Final Payload ----------
const renderJson = {
  timeline: {
    background: "#000000",
    tracks: [{ clips: videoClips }, ...audioTracks],
  },
  output: {
    format: "mp4",
    size: { width: 1080, height: 1080 },
  },
};

return [{ json: renderJson }];

