const fileId = $json.id;
const captionUrl = `https://drive.google.com/uc?export=download&id=${fileId}`;

return [{
  json: {
    captionUrl
  }
}];

function parseTime(str) {
  const [hms, ms] = str.split(',');
  const [h, m, s] = hms.split(':').map(Number);
  return h * 3600 + m * 60 + s + Number(ms) / 1000;
}

function formatTime(seconds) {
  const h = String(Math.floor(seconds / 3600)).padStart(2, '0');
  const m = String(Math.floor((seconds % 3600) / 60)).padStart(2, '0');
  const s = String(Math.floor(seconds % 60)).padStart(2, '0');
  const ms = String(Math.floor((seconds % 1) * 1000)).padStart(3, '0');
  return `${h}:${m}:${s},${ms}`;
}

function chunkText(text, chunkSize = 7) {
  const words = text.split(' ');
  const chunks = [];
  for (let i = 0; i < words.length; i += chunkSize) {
    chunks.push(words.slice(i, i + chunkSize).join(' '));
  }
  return chunks;
}

const srt = $json.data || $json.srt || $json; // Adjust depending on your input
const lines = srt.split('\n');

let block = [];
let counter = 1;
let newSrt = '';

for (let i = 0; i < lines.length; i++) {
  if (lines[i].trim() === '') {
    if (block.length >= 3) {
      const time = block[1];
      const [start, end] = time.split(' --> ');
      const startSec = parseTime(start.trim());
      const endSec = parseTime(end.trim());
      const duration = endSec - startSec;

      const text = block.slice(2).join(' ');
      const chunks = chunkText(text, 7);

      const chunkDuration = duration / chunks.length;

      chunks.forEach((chunk, j) => {
        const chunkStart = startSec + j * chunkDuration;
        const chunkEnd = chunkStart + chunkDuration;
        newSrt += `${counter}\n${formatTime(chunkStart)} --> ${formatTime(chunkEnd)}\n${chunk}\n\n`;
        counter++;
      });
    }
    block = [];
  } else {
    block.push(lines[i]);
  }
}

return [{ json: { srt: newSrt } }];

// 🎵 List of your Google Drive music URLs
const musicLinks = [
  "https://drive.google.com/file/d/1N7uQOJavWoB934jeAf-BRQ7VGfkLD84J/view?usp=drive_link",
  "https://drive.google.com/file/d/1pe7aVFZRtcIR7k1QpS9b1dp2H6jfkFPV/view?usp=drive_link",
  "https://drive.google.com/file/d/17xPY6Oq9JfKVnehqUVMLMk_Kb8JW_R8D/view?usp=drive_link",
  "https://drive.google.com/file/d/1c3w3DKlFBe5xJvu7KgE7Lhxbyq2-KXl8/view?usp=drive_link",
  "https://drive.google.com/file/d/1xbvCSgYWDR3Jossn7o5HsMgdfMX1LG5E/view?usp=drive_link"
];

// 🎼 Optional genre labels (in same order as above)
const genres = [
  "Cinematic Inspiration",
  "Ambient Flow",
  "Uplifting Corporate",
  "Calm Piano",
  "Energetic Beat"
];

// 🔄 Convert to direct download format
const convertToDirect = (link) => {
  const match = link.match(/\/d\/(.*?)(\/|$)/);
  if (match && match[1]) {
    return `https://drive.google.com/uc?export=download&id=${match[1]}`;
  }
  return link; // fallback if not a Drive link
};

// 🧠 Map all links
const allTracks = musicLinks.map((link, index) => ({
  name: genres[index] || `Track ${index + 1}`,
  original: link,
  direct: convertToDirect(link)
}));

// 🎲 Pick a random one
const selected = allTracks[Math.floor(Math.random() * allTracks.length)];

// ✅ Output result
return [{
  json: {
    selectedMusic: selected,
    allTracks: allTracks
  }
}];
